mapper.select:
SELECT w.WISH_ID, w.CREATED_AT, w.USER_ID, w.PRODUCT_ID, p.PRODUCT_NAME, p.PRICE, c.CATEGORY_NAME AS categoryName, b.BRAND_NAME AS brandName, i.IMG_URL AS imgUrl FROM WISHLIST w INNER JOIN PRODUCT p ON w.PRODUCT_ID = p.PRODUCT_ID LEFT JOIN PRODUCT_CATEGORY c ON p.CATEGORY_ID = c.CATEGORY_ID LEFT JOIN BRAND b ON p.BRAND_ID = b.BRAND_ID LEFT JOIN ( SELECT PRODUCT_ID, MIN(IMG_URL) AS IMG_URL FROM PRODUCT_IMG WHERE IS_MAIN = 'Y' GROUP BY PRODUCT_ID ) i ON p.PRODUCT_ID = i.PRODUCT_ID WHERE w.USER_ID = #{userId}
AND ( p.PRODUCT_NAME LIKE CONCAT('%', #{keyword}, '%') OR c.CATEGORY_NAME LIKE CONCAT('%', #{keyword}, '%') OR b.BRAND_NAME LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY w.CREATED_AT DESC, w.WISH_ID DESC LIMIT ${start}, ${pageSize}

mapper.delete:
DELETE FROM WISHLIST
WHERE WISH_ID = #{wishId}
AND USER_ID = #{userId}
